import re
from taf.selenium.gnb.oam.coam.classical.facade import Coam, Coam20B, Coam21A, Coam21B


class SupportedCoams(object):
    coam = Coam
    coam20b = Coam20B
    coam21a = Coam21A
    coam21b = Coam21B


class Provider(object):
    @classmethod
    def provide(cls, version=None):
        regex_for_verison = "(?:5[gG])?(.*)?"
        if version == "" or version is None:
            supported_coam = "coam"
        else:
            version_parsed = re.search(regex_for_verison, version).groups()[0]
            supported_coam = "coam{version}".format(version=version_parsed.lower())

        coam_cls = getattr(SupportedCoams, supported_coam, SupportedCoams.coam)
        return coam_cls
